from pathlib import Path
import json, re, sys

CID="AUTO-DISCOVERY-54d13314c7879b58e46d"
MODEL_TASK="A2Z-V4-ASTRA-POSTBUILD-20261006-R3-P2"
roots=[
 Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4",
 Path.home()/".local/share/prediction-project-executor/worktrees/DEV-PRED-A2Z-POSTBUILD-RETRY-20261006-E106",
 Path.home()/".local/state/prediction-codex-supervisor",
]
records=[]

def walk(o,path):
 if isinstance(o,dict):
  dec=str(o.get("decision","")).upper()
  blob=json.dumps(o,sort_keys=True,default=str)
  if dec in {"APPROVE","NEEDS_REVISION","REVISE","REJECT","PARK"} and (
      CID in blob or MODEL_TASK in blob or "POSTBUILD" in blob.upper() or "postbuild" in path.lower()):
   records.append((path,o))
  for v in o.values(): walk(v,path)
 elif isinstance(o,list):
  for v in o: walk(v,path)

for root in roots:
 if not root.exists(): continue
 for p in root.rglob("*"):
  try:
   if not p.is_file() or p.stat().st_size>2000000: continue
  except OSError: continue
  if p.suffix.lower() not in {".json",".jsonl"}: continue
  try: raw=p.read_text(errors="replace")
  except Exception: continue
  low=raw.lower()
  if CID.lower() not in low and MODEL_TASK.lower() not in low and "postbuild" not in low: continue
  if p.suffix.lower()==".json":
   try: walk(json.loads(raw),str(p))
   except Exception: pass
  else:
   for line in raw.splitlines():
    try: walk(json.loads(line),str(p))
    except Exception: pass

uniq=[]; seen=set()
for path,d in records:
 key=(path,json.dumps(d,sort_keys=True,default=str))
 if key in seen: continue
 seen.add(key); uniq.append((path,d))

def pick(d,names):
 for n in names:
  v=d.get(n)
  if v not in (None,""): return n,v
 return None,None

summ=[]
for path,d in uniq:
 phase_k,phase=pick(d,["phase","review_phase","gate","review_kind"])
 model_k,model=pick(d,["reviewer_model","model","model_display_name"])
 slug_k,slug=pick(d,["reviewer_model_slug","model_slug","selected_slug"])
 bind_k,bind=pick(d,["binding_sha256","review_binding_sha256","build_binding_sha256","binding_hash","binding"])
 provref_k,provref=pick(d,["model_provenance_ref","provenance_ref"])
 provsha_k,provsha=pick(d,["model_provenance_sha256","provenance_sha256"])
 task_k,task=pick(d,["source_task_id","task_id","model_task_id","review_task_id"])
 summ.append({
  "file":Path(path).name,
  "decision":str(d.get("decision","")).upper(),
  "phase":phase,
  "model":model,
  "slug":slug,
  "binding_field":bind_k,
  "binding64":bool(isinstance(bind,str) and re.fullmatch(r"[0-9a-f]{64}",bind)),
  "prov_ref":bool(provref),
  "prov_sha64":bool(isinstance(provsha,str) and re.fullmatch(r"[0-9a-f]{64}",provsha)),
  "task":task,
  "candidate":d.get("candidate_id"),
 })

# compact unique summaries
compact=[]
seen2=set()
for x in summ:
 key=tuple((k,str(v)) for k,v in x.items() if k!="file")
 if key in seen2: continue
 seen2.add(key); compact.append(x)

# Determine strongest assessment, not authorization.
exact=[x for x in compact if x["decision"]=="APPROVE" and str(x["phase"]).upper()=="POSTBUILD" and x["model"]=="GPT-6 Astra" and x["slug"]=="gpt-6-astra" and x["binding64"] and x["prov_ref"] and x["prov_sha64"]]
if exact:
 assessment="EXACT_FIELDS_PRESENT"
else:
 missing=[]
 approvals=[x for x in compact if x["decision"]=="APPROVE"]
 if not approvals:
  assessment="NO_APPROVE_RECORD"
 else:
  for field,ok in [
   ("phase",any(str(x["phase"]).upper()=="POSTBUILD" for x in approvals)),
   ("model",any(x["model"]=="GPT-6 Astra" for x in approvals)),
   ("slug",any(x["slug"]=="gpt-6-astra" for x in approvals)),
   ("binding64",any(x["binding64"] for x in approvals)),
   ("provenance_ref",any(x["prov_ref"] for x in approvals)),
   ("provenance_sha64",any(x["prov_sha64"] for x in approvals)),
  ]:
   if not ok: missing.append(field)
  assessment="MISSING_"+",".join(missing) if missing else "FIELDS_SPLIT_ACROSS_RECORDS"

out={"assessment":assessment,"records":compact[:6]}
print("E106_COMPACT_CLASSIFY "+json.dumps(out,separators=(",",":")),flush=True)
raise SystemExit(0)
